ALTER TABLE accounting_close ADD COLUMN workpaperSnapshotJson TEXT;
ALTER TABLE accounting_month_lock ADD COLUMN documentsJson TEXT NOT NULL DEFAULT '[]';
CREATE TABLE accounting_preparation (month TEXT NOT NULL PRIMARY KEY, version INTEGER NOT NULL DEFAULT 1, checklistJson TEXT NOT NULL, note TEXT NOT NULL, updatedBy TEXT NOT NULL, updatedAt DATETIME NOT NULL);
CREATE TABLE accounting_preparation_revision (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, scope TEXT NOT NULL, beforeJson TEXT NOT NULL, afterJson TEXT NOT NULL, reason TEXT NOT NULL, createdBy TEXT NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX accounting_preparation_revision_scope_createdAt_idx ON accounting_preparation_revision(scope, createdAt);
CREATE TABLE accounting_document (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, requestKey TEXT NOT NULL, month TEXT NOT NULL, sourceKey TEXT NOT NULL, category TEXT NOT NULL, originalName TEXT NOT NULL, mimeType TEXT NOT NULL, sizeBytes INTEGER NOT NULL, sha256 TEXT NOT NULL, fileData BLOB NOT NULL, createdBy TEXT NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX accounting_document_requestKey_key ON accounting_document(requestKey);
CREATE UNIQUE INDEX accounting_document_month_sourceKey_key ON accounting_document(month, sourceKey);
CREATE INDEX accounting_document_month_idx ON accounting_document(month);
CREATE TABLE accounting_year_workpaper (year TEXT NOT NULL PRIMARY KEY, version INTEGER NOT NULL DEFAULT 1, accountsJson TEXT NOT NULL, equityJson TEXT NOT NULL, notes TEXT NOT NULL, updatedBy TEXT NOT NULL, updatedAt DATETIME NOT NULL);
CREATE TABLE accounting_adjustment (id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, requestKey TEXT NOT NULL, year TEXT NOT NULL, occurredOn TEXT NOT NULL, description TEXT NOT NULL, linesJson TEXT NOT NULL, createdBy TEXT NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX accounting_adjustment_requestKey_key ON accounting_adjustment(requestKey);
CREATE INDEX accounting_adjustment_year_occurredOn_idx ON accounting_adjustment(year, occurredOn);
CREATE TRIGGER preparation_no_locked_insert BEFORE INSERT ON accounting_preparation WHEN EXISTS(SELECT 1 FROM accounting_month_lock WHERE endOn >= NEW.month || '-01') BEGIN SELECT RAISE(ABORT, 'Month is locked'); END;
CREATE TRIGGER preparation_no_locked_update BEFORE UPDATE ON accounting_preparation WHEN NEW.month != OLD.month OR EXISTS(SELECT 1 FROM accounting_month_lock WHERE endOn >= OLD.month || '-01') BEGIN SELECT RAISE(ABORT, 'Month is locked'); END;
CREATE TRIGGER preparation_no_delete BEFORE DELETE ON accounting_preparation BEGIN SELECT RAISE(ABORT, 'Preparation history cannot be deleted'); END;
CREATE TRIGGER document_no_locked_insert BEFORE INSERT ON accounting_document WHEN EXISTS(SELECT 1 FROM accounting_month_lock WHERE endOn >= NEW.month || '-01') OR EXISTS(SELECT 1 FROM accounting_close WHERE endOn >= NEW.month || '-01') BEGIN SELECT RAISE(ABORT, 'Month is locked'); END;
CREATE TRIGGER document_no_update BEFORE UPDATE ON accounting_document BEGIN SELECT RAISE(ABORT, 'Documents are immutable'); END;
CREATE TRIGGER document_no_delete BEFORE DELETE ON accounting_document BEGIN SELECT RAISE(ABORT, 'Documents are immutable'); END;
CREATE TRIGGER preparation_revision_no_update BEFORE UPDATE ON accounting_preparation_revision BEGIN SELECT RAISE(ABORT, 'Audit history is immutable'); END;
CREATE TRIGGER preparation_revision_no_delete BEFORE DELETE ON accounting_preparation_revision BEGIN SELECT RAISE(ABORT, 'Audit history is immutable'); END;
CREATE TRIGGER year_workpaper_no_closed_insert BEFORE INSERT ON accounting_year_workpaper WHEN EXISTS(SELECT 1 FROM accounting_close WHERE startOn <= NEW.year || '-12-31' AND endOn >= NEW.year || '-01-01') BEGIN SELECT RAISE(ABORT, 'Year is closed'); END;
CREATE TRIGGER year_workpaper_no_closed_update BEFORE UPDATE ON accounting_year_workpaper WHEN NEW.year != OLD.year OR EXISTS(SELECT 1 FROM accounting_close WHERE startOn <= OLD.year || '-12-31' AND endOn >= OLD.year || '-01-01') BEGIN SELECT RAISE(ABORT, 'Year is closed'); END;
CREATE TRIGGER year_workpaper_no_delete BEFORE DELETE ON accounting_year_workpaper BEGIN SELECT RAISE(ABORT, 'Workpaper history cannot be deleted'); END;
CREATE TRIGGER adjustment_no_closed_insert BEFORE INSERT ON accounting_adjustment WHEN EXISTS(SELECT 1 FROM accounting_close WHERE startOn <= NEW.year || '-12-31' AND endOn >= NEW.year || '-01-01') BEGIN SELECT RAISE(ABORT, 'Year is closed'); END;
CREATE TRIGGER adjustment_no_update BEFORE UPDATE ON accounting_adjustment BEGIN SELECT RAISE(ABORT, 'Adjustments are immutable; post a reversal'); END;
CREATE TRIGGER adjustment_no_delete BEFORE DELETE ON accounting_adjustment BEGIN SELECT RAISE(ABORT, 'Adjustments are immutable; post a reversal'); END;
-- The historical cashbook participates in month locks without being merged into the loan ledger.
CREATE TRIGGER historical_cash_closed_insert BEFORE INSERT ON historical_cash_entry WHEN EXISTS(SELECT 1 FROM accounting_month_lock WHERE NEW.occurredOn <= endOn) BEGIN SELECT RAISE(ABORT, 'Accounting month is locked'); END;
CREATE TRIGGER historical_cash_closed_update BEFORE UPDATE ON historical_cash_entry WHEN EXISTS(SELECT 1 FROM accounting_month_lock WHERE OLD.occurredOn <= endOn OR NEW.occurredOn <= endOn) BEGIN SELECT RAISE(ABORT, 'Accounting month is locked'); END;
CREATE TRIGGER historical_cash_closed_delete BEFORE DELETE ON historical_cash_entry WHEN EXISTS(SELECT 1 FROM accounting_month_lock WHERE OLD.occurredOn <= endOn) BEGIN SELECT RAISE(ABORT, 'Accounting month is locked'); END;
